#!/usr/bin/env bash
# Round 10 (R10 retention) art: Cat Street upgrades + new shops, Daily record rewards, album prints and icons.
# ONE at a time via studio/bin/art.sh. usage: r10.sh [name...]  (FORCE=1 to redo). Processed by proc_r10.py.
cd /c/Users/Admin/Documents/Msjelly/studio/long-cat-out/art-src/r7
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green walls #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
G="Arrange as a clean grid with wide magenta gaps between items, each item fully visible and the same scale."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n $(date +%T)"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }

run street_up_sign && g street_up_sign "Six standalone street props, one signature upgrade for each shop of a cozy cat town, each placed on the pavement beside a shop door, straight front view, same scale (each about as tall as a door): (1) a wooden bread cart with wicker baskets of loaves and a little striped canopy; (2) a tall ornate iron street reading lamp whose warm glowing lantern sits on top of a stack of big books, light glowing; (3) a small flower cart with a wooden wheel overflowing with tulips and roses; (4) an outdoor tea table with a round teal tablecloth, a teapot, two cups and two floor cushions; (5) a colourful wooden toy stand with a spinning pinwheel, a rocking horse and yarn balls; (6) a little wooden busker stage with a shiny brass tuba and a music stand. Arrange as 2 rows x 3 columns. $K $G $S"
run street_up_shared && g street_up_shared "Three shop-front decorations for a cozy cat town, straight front view, each fully separate: (1) a long wide bunting garland of small triangular cloth flags in pastel peach, sage, cream and rust on a gently sagging string, much wider than tall; (2) a long wooden window planter box overflowing with flowers and trailing ivy, much wider than tall; (3) a long gently sagging string of warm glowing round fairy light bulbs, much wider than tall. Arrange as 3 rows x 1 column, one item per row. $K $S"
run street_shops_c && g street_shops_c "Three narrow two-storey storybook shop houses for a town of cats, straight front view, each a complete standalone building with its own roof and doorstep, all the same width and height: (1) a fish market with a white and sky-blue striped awning, crates of cute fish by the door and a blank fish-shaped sign board with no lettering; (2) a post office with a brick-red facade, a round clock above the door and a little red mailbox beside it; (3) a yarn and knitting shop with a lavender facade, big balls of yarn in the window and knitted bunting. Little cat-ear shapes on each roof. Left to right in one row. $K $S"
run keepers_c && g keepers_c "Three chubby cute felt-toy cats, the shopkeepers of a cat town, full body sitting, front 3/4 view, same scale: (1) a sturdy orange cat in a yellow fisherman raincoat and hat holding a small fish; (2) a white cat in a blue postal cap with a brown satchel holding a letter; (3) a fluffy lilac-grey cat with a knitted scarf holding knitting needles and a ball of yarn. Left to right in one row. $K $S"
run daily_rewards && g daily_rewards "Three cozy cat cafe trophies, front view, same scale: (1) an ornate golden oval portrait frame with tiny paw prints and a little bow at the top, the inside of the frame is EMPTY and shows the magenta background through it; (2) a triangular felt cafe pennant flag in rust red and cream on a small wooden stick with a cute paw print emblem, no letters; (3) a round wooden wall clock with cat ears and a little cat-tail pendulum, simple dots instead of numbers. Left to right in one row. $K $S"
run prints && g prints "Six small framed paintings to hang on a cafe wall, each a cute painterly picture in a chunky honey oak picture frame, straight front view, same frame size: (1) cats napping together on a soft sofa; (2) a sunny cobblestone street of little shop houses; (3) a tree split into autumn, winter and spring; (4) a proud cat on a small winner podium wearing a ribbon rosette; (5) a kitten playing with a big ball of yarn on a checkered table; (6) three tiny kittens sleeping in a wicker basket. Arrange as 2 rows x 3 columns. $K $G $S"
run album_ui && g album_ui "Three cozy game icons, front view, same scale: (1) a closed photo album book with a soft sage fabric cover, golden corners and a cute paw print on the cover; (2) a round rust-red postal postmark stamp badge with wavy edges and a paw print in the middle, no letters; (3) a cream paper envelope sealed with a red heart wax seal. Left to right in one row. $K $S"
echo "all done $(date +%T)"
